                logger.exception("动作子表补字段失败 shop=%s", shop)

    return {
        "created": int(stats.get("mother") or 0),
        "skipped": 0,
        "total": int(stats.get("mother") or 0),
        "children": int(stats.get("children") or 0),
    }


