"""店铺名称规范化与按店飞书子表注册表。

规范名（canonical）用于：
  - 子表命名：ASIN每日数据__Ledvia-UK
  - 写入路由：raw shop_name → canonicalize → 子表 table_id
"""

from __future__ import annotations

import json
import logging
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterable

from app.config import ROOT_DIR, get_app_config, get_settings

logger = logging.getLogger(__name__)

# 默认别名 → 规范店名
DEFAULT_SHOP_ALIASES: dict[str, str] = {
    "LEDVIE": "Ledvia-UK",
    "Ledvia": "Ledvia-UK",
    "Ledvia-UK": "Ledvia-UK",
    "ledvia": "Ledvia-UK",
    "ledvie": "Ledvia-UK",
    "NOTTAC": "Nottac-UK",
    "Nottac": "Nottac-UK",
    "Nottac-UK": "Nottac-UK",
    "nottac": "Nottac-UK",
    "特米": "特米-UK",
    "特米-UK": "特米-UK",
    "昇新": "昇新-UK",
    "昇新-UK": "昇新-UK",
    "SHENGXIN": "昇新-UK",
    "起的快": "起的快-UK",
    "起的快-UK": "起的快-UK",
    "字同": "字同道合",
    "字同道合": "字同道合",
}

# 逻辑表 kind → 母表中文名（与 TABLE_SPECS 一致）
KIND_TO_MOTHER_NAME: dict[str, str] = {
    "asin_daily": "ASIN每日数据",
    "tasks": "异常任务",
    "actions": "运营动作记录",
    "config": "配置表",
    "daily_summary": "每日汇总",
    "product_master": "产品主档案",
}

TABLE_KINDS: tuple[str, ...] = tuple(KIND_TO_MOTHER_NAME.keys())


def load_alias_map() -> dict[str, str]:
    m = dict(DEFAULT_SHOP_ALIASES)
    cfg = get_app_config()
    extra = cfg.get("shop_aliases") or {}
    if isinstance(extra, dict):
        for k, v in extra.items():
            if k and v:
                m[str(k).strip()] = str(v).strip()
    return m


def canonicalize_shop(name: str | None, aliases: dict[str, str] | None = None) -> str:
    """原始店名 → 规范名；空串返回空串。"""
    if not name:
        return ""
    name = str(name).strip()
    if not name:
        return ""
    aliases = aliases if aliases is not None else load_alias_map()
    if name in aliases:
        return aliases[name]
    lower = {k.lower(): v for k, v in aliases.items()}
    return lower.get(name.lower(), name)


def shop_match_variants(
    canonical: str, aliases: dict[str, str] | None = None
) -> list[str]:
    """规范名对应的全部写法（含自身），规范名在前。"""
    aliases = aliases if aliases is not None else load_alias_map()
    names = {canonical}
    for alias, can in aliases.items():
        if can == canonical:
            names.add(alias)
    rest = sorted(n for n in names if n != canonical)
    return [canonical] + rest


def list_canonical_shops_from_names(names: Iterable[str]) -> list[str]:
    aliases = load_alias_map()
    seen: set[str] = set()
    out: list[str] = []
    for n in names:
        can = canonicalize_shop(n, aliases)
        if can and can not in seen:
            seen.add(can)
            out.append(can)
    return sorted(out)


def list_canonical_shops_from_db(db_path: Path | None = None) -> list[str]:
    from app.store.db import Database

    settings = get_settings()
    path = Path(db_path or settings.db_path)
    if not path.exists():
        return list_canonical_shops_from_names(load_alias_map().values())
    db = Database(path)
    with db.connect() as conn:
        rows = conn.execute(
            "SELECT DISTINCT shop_name FROM asin_daily "
            "WHERE shop_name IS NOT NULL AND shop_name != ''"
        ).fetchall()
    raw = [str(r["shop_name"]) for r in rows]
    cans = list_canonical_shops_from_names(raw)
    if not cans:
        cans = list_canonical_shops_from_names(load_alias_map().values())
    return cans


def child_table_name(mother_name: str, canonical_shop: str) -> str:
    """子表命名：ASIN每日数据__Ledvia-UK"""
    return f"{mother_name}__{canonical_shop}"


def parse_child_table_name(name: str) -> tuple[str, str] | None:
    """解析 母表名__店名 → (mother, shop)；非分表名返回 None。"""
    if "__" not in name:
        return None
    mother, shop = name.rsplit("__", 1)
    if not mother or not shop:
        return None
    return mother, shop


@dataclass
class ShopTableRegistry:
    """shop → {kind: table_id}"""

    data: dict[str, dict[str, str]] = field(default_factory=dict)
    path: Path | None = None

    def get(self, canonical_shop: str, kind: str) -> str | None:
        shop = self.data.get(canonical_shop) or {}
        tid = shop.get(kind)
        return tid if tid else None

    def set(self, canonical_shop: str, kind: str, table_id: str) -> None:
        self.data.setdefault(canonical_shop, {})[kind] = table_id

    def shops(self) -> list[str]:
        return sorted(self.data.keys())

    def all_table_ids(self, kind: str) -> list[tuple[str, str]]:
        """[(shop, table_id), ...]"""
        out = []
        for shop, kinds in sorted(self.data.items()):
            tid = kinds.get(kind)
            if tid:
                out.append((shop, tid))
        return out

    def save(self, path: Path | None = None) -> Path:
        p = Path(path or self.path or default_registry_path())
        p.parent.mkdir(parents=True, exist_ok=True)
        with p.open("w", encoding="utf-8") as f:
            json.dump(self.data, f, ensure_ascii=False, indent=2)
        self.path = p
        return p

    @classmethod
    def load(cls, path: Path | None = None) -> ShopTableRegistry:
        p = Path(path or default_registry_path())
        if not p.exists():
            return cls(data={}, path=p)
        try:
            with p.open("r", encoding="utf-8") as f:
                raw = json.load(f) or {}
            if not isinstance(raw, dict):
                return cls(data={}, path=p)
            data: dict[str, dict[str, str]] = {}
            for shop, kinds in raw.items():
                if isinstance(kinds, dict):
                    data[str(shop)] = {
                        str(k): str(v) for k, v in kinds.items() if k and v
                    }
            return cls(data=data, path=p)
        except Exception:
            logger.exception("加载 shop table registry 失败: %s", p)
            return cls(data={}, path=p)


def default_registry_path() -> Path:
    settings = get_settings()
    # 允许 env / 配置覆盖
    cfg = get_app_config()
    sync = cfg.get("sync") or {}
    custom = sync.get("shop_tables_path") or ""
    if custom:
        p = Path(custom)
        if not p.is_absolute():
            p = ROOT_DIR / p
        return p
    return Path(settings.data_dir) / "feishu_shop_tables.json"


def dual_write_enabled() -> bool:
    cfg = get_app_config()
    sync = cfg.get("sync") or {}
    return bool(sync.get("dual_write_shop_tables", True))


def group_rows_by_canonical_shop(
    rows: list[dict[str, Any]],
    *,
    shop_key: str = "shop_name",
) -> dict[str, list[dict[str, Any]]]:
    """按规范店名分组；无法解析的进 key ''。"""
    aliases = load_alias_map()
    groups: dict[str, list[dict[str, Any]]] = {}
    for r in rows:
        raw = r.get(shop_key) or r.get("店铺") or ""
        can = canonicalize_shop(str(raw) if raw else "", aliases)
        groups.setdefault(can, []).append(r)
    return groups

#!/usr/bin/env python3
"""按逻辑店铺创建飞书业务子表（母表保留，命名：母表名__规范店名）。

用法:
  python scripts/init_shop_tables.py --dry-run
  python scripts/init_shop_tables.py
  python scripts/init_shop_tables.py --shops Ledvia-UK,Nottac-UK
"""
from __future__ import annotations

import argparse
import copy
import sys
import time
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from app.clients.feishu import FeishuClient, FeishuError
from app.config import get_settings
from app.sync.feishu_schema import TABLE_SPECS
from app.sync.shops import (
    KIND_TO_MOTHER_NAME,
    ShopTableRegistry,
    TABLE_KINDS,
    child_table_name,
    default_registry_path,
    list_canonical_shops_from_db,
    list_canonical_shops_from_names,
)

# TABLE_SPECS env_key → kind
ENV_TO_KIND = {
    "FEISHU_TABLE_ASIN_DAILY": "asin_daily",
    "FEISHU_TABLE_TASKS": "tasks",
    "FEISHU_TABLE_ACTIONS": "actions",
    "FEISHU_TABLE_CONFIG": "config",
    "FEISHU_TABLE_DAILY_SUMMARY": "daily_summary",
    "FEISHU_TABLE_PRODUCT_MASTER": "product_master",
}


def _fields_for_create(mother_name: str, fields: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """创建时去掉单向关联(type=18)：需指向动作子表，稍后单独补。"""
    out = []
    for f in fields:
        f = copy.deepcopy(f)
        if f.get("type") == 18:
            continue  # 关联运营动作 等
        # create_table 不接受非法 property
        out.append(f)
    return out


def main() -> int:
    parser = argparse.ArgumentParser(description="初始化按店飞书子表")
    parser.add_argument("--shops", default="", help="逗号分隔规范店名；默认从本地库")
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument(
        "--registry",
        default="",
        help="输出 JSON 路径，默认 data/feishu_shop_tables.json",
    )
    args = parser.parse_args()

    settings = get_settings()
    if not settings.has_feishu or not settings.feishu_bitable_app_token:
        print("ERROR: 需要 FEISHU_APP_ID/SECRET 与 FEISHU_BITABLE_APP_TOKEN")
        return 2

    if args.shops.strip():
        shops = list_canonical_shops_from_names(
            [s.strip() for s in args.shops.split(",") if s.strip()]
        )
    else:
        shops = list_canonical_shops_from_db()

    if not shops:
        print("ERROR: 无规范店铺列表")
        return 2

    registry_path = Path(args.registry) if args.registry else default_registry_path()
    print(f"逻辑店铺({len(shops)}): {shops}")
    print(f"registry → {registry_path}")
    print(f"kinds: {list(TABLE_KINDS)}")

    planned = []
    for shop in shops:
        for kind, mother in KIND_TO_MOTHER_NAME.items():
            planned.append((shop, kind, child_table_name(mother, shop)))
    print(f"将确保 {len(planned)} 张子表")
    if args.dry_run:
        for shop, kind, name in planned:
            print(f"  {name}  ({kind})")
        print("[DRY-RUN] 未调用飞书")
        return 0

    # mother_name → fields
    name_to_fields = {s["name"]: s["fields"] for s in TABLE_SPECS}
    name_to_kind = {}
    for s in TABLE_SPECS:
        kind = ENV_TO_KIND.get(s["env_key"])
        if kind:
            name_to_kind[s["name"]] = kind

    registry = ShopTableRegistry.load(registry_path)
    app = settings.feishu_bitable_app_token

    try:
        with FeishuClient(settings) as client:
            existing = {
                t.get("name"): t.get("table_id")
                for t in client.list_tables(app)
                if t.get("name") and t.get("table_id")
            }
            print(f"base 已有表 {len(existing)} 张")

            # 先建非 tasks 关联依赖：全部表先建（tasks 去掉 link 字段）
            for shop in shops:
                for mother_name, kind in [
                    (KIND_TO_MOTHER_NAME[k], k) for k in TABLE_KINDS
                ]:
                    tname = child_table_name(mother_name, shop)
                    if tname in existing and existing[tname]:
                        tid = existing[tname]
                        print(f"exists: {tname} -> {tid}")
                        registry.set(shop, kind, tid)
                        continue
                    fields = name_to_fields.get(mother_name) or []
                    create_fields = _fields_for_create(mother_name, fields)
                    print(f"create: {tname} ({len(create_fields)} fields) ...")
                    try:
                        data = client.create_table(app, tname, create_fields)
                        tid = (
                            data.get("table_id")
                            or (data.get("table") or {}).get("table_id")
                            or ""
                        )
                        if not tid:
                            print(f"  FAIL no table_id: {data}")
                            continue
                        print(f"  OK {tid}")
                        existing[tname] = tid
                        registry.set(shop, kind, tid)
                        time.sleep(0.35)
                    except FeishuError as e:
                        print(f"  FAIL [{e.code}] {e.message}")

            # 补 tasks 子表 → actions 子表 的单向关联字段
            for shop in shops:
                task_tid = registry.get(shop, "tasks")
                action_tid = registry.get(shop, "actions")
                if not task_tid or not action_tid:
                    continue
                try:
                    names = {
                        f.get("field_name")
                        for f in client.list_fields(app, task_tid)
                        if f.get("field_name")
                    }
                    if "关联运营动作" in names:
                        continue
                    client.create_field(
                        app,
                        task_tid,
                        "关联运营动作",
                        18,
                        property_={"table_id": action_tid},
                    )
                    print(f"link field OK: tasks__{shop} → actions__{shop}")
                    time.sleep(0.2)
                except FeishuError as e:
                    print(f"link field skip {shop}: [{e.code}] {e.message}")

            # 动作定位列
            for shop in shops:
                action_tid = registry.get(shop, "actions")
                if not action_tid:
                    continue
                try:
                    from app.sync.writer import ACTION_SYSTEM_FIELD_NAMES

                    created = client.ensure_text_fields(
                        app, action_tid, ACTION_SYSTEM_FIELD_NAMES
                    )
                    if created:
                        print(f"action cols {shop}: {created}")
                except Exception as e:
                    print(f"action cols skip {shop}: {e}")

        path = registry.save(registry_path)
        print(f"\n✅ 已写入注册表: {path}")
        print(json_summary(registry))
        return 0
    except FeishuError as e:
        print(f"FEISHU ERROR [{e.code}] {e.message}")
        return 1


def json_summary(registry: ShopTableRegistry) -> str:
    lines = ["shops:"]
    for shop in registry.shops():
        kinds = registry.data.get(shop) or {}
        lines.append(f"  {shop}: {len(kinds)} kinds")
    return "\n".join(lines)


